SELECT sm.id AS master_id,sm.title,sm.track,sm.disc,sm.album_id,a.name AS album_name FROM song_masters sm JOIN albums a ON a.id=sm.album_id WHERE sm.album_id!='pending-uploads' AND lower(trim(sm.title)) IN ('流年烹茶','浅浅话','深夜电台','温柔的杀戮者','游戏少女','渺小祈愿','漂流','点滴','烟霞行吟','烦恼不如跳舞','热烈散场-干杯2025','焰色空白格','燕双归','狮子座','玻璃做的少女','理想城演出指南','瑕疵品','瓶中烟花','瓶中烟花-永夜minus','生命中不曾遇见的她','生而为人，我很抱歉','生而为枭','白羊座','相思若循','相虎','睡蓮のマーメイドと、もう子供じゃない貴方','破云来','祖龙吟','神秘的预言者','离开与回到夏天的言语','积极消极','竹林间','笑疏狂','笼中藤','簪花人间') ORDER BY sm.title,sm.album_id